mapper.select:
select sid, app_id, waste_name, directory_id, storage_quantity, measurement_unit_code, measurement_unit_name, storage_position_code, storage_position_name, storage_position_type, responsible_person_id, responsible_person_name, file_id, remark, update_by, update_time, create_by, create_time, tenant_id, tenant_name, del_flag from hse_hazardous_waste_base where sid in
#{item}
and del_flag=0

select
sid,
app_id,
waste_name,
directory_id,
storage_quantity,
measurement_unit_code,
measurement_unit_name,
storage_position_code,
storage_position_name,
storage_position_type,
responsible_person_id,
responsible_person_name,
file_id,
remark,
update_by,
update_time,
create_by,
create_time,
tenant_id,
tenant_name,
del_flag

from hse_hazardous_waste_base
where app_id = #{appId} and del_flag=0


    and sid = #{sid}


    and app_id = #{appId}


    and waste_name = #{wasteName}


    and directory_id = #{directoryId}


    and storage_quantity = #{storageQuantity}


    and measurement_unit_code = #{measurementUnitCode}


    and measurement_unit_name = #{measurementUnitName}


    and storage_position_code = #{storagePositionCode}


    and storage_position_name = #{storagePositionName}


    and storage_position_type = #{storagePositionType}


    and responsible_person_id = #{responsiblePersonId}


    and responsible_person_name = #{responsiblePersonName}


    and file_id = #{fileId}


    and remark = #{remark}


    and update_by = #{updateBy}


    and update_time = #{updateTime}


    and create_by = #{createBy}


    and create_time = #{createTime}


    and tenant_id = #{tenantId}


    and tenant_name = #{tenantName}


    and del_flag = #{delFlag}

select
base.sid as sid,
base.app_id as appId,
base.waste_name as wasteName,
base.directory_id as directoryId,
base.storage_quantity as storageQuantity,
base.measurement_unit_code as measurementUnitCode,
base.measurement_unit_name as measurementUnitName,
base.storage_position_code as storagePositionCode,
base.storage_position_name as storagePositionName,
base.storage_position_type as storagePositionType,
base.responsible_person_id as responsiblePersonId,
base.responsible_person_name as responsiblePersonName,
base.file_id as fileId,
base.remark as remark,

directory.type as type,
directory.waste_code as wasteCode,
directory.name as name


from hse_hazardous_waste_base base
left join hse_hazardous_waste_directory directory
on base.directory_id = directory.sid


where base.app_id = #{appId} and base.del_flag = 0 and directory.app_id = #{appId} and directory.del_flag = 0


    and (
    base.waste_name like concat('%',#{keyWord},'%')
    or base.storage_position_name like concat('%',#{keyWord},'%')
    or base.responsible_person_name like concat('%',#{keyWord},'%')
    or directory.name like concat('%',#{keyWord},'%')
    or directory.waste_code like concat('%',#{keyWord},'%')
    or directory.type like concat('%',#{keyWord},'%')
    )




    and base.waste_name = #{wasteName}


    and base.directory_id = #{directoryId}


    and base.storage_quantity = #{storageQuantity}


    and base.measurement_unit_code = #{measurementUnitCode}


    and base.measurement_unit_name = #{measurementUnitName}


    and base.storage_position_code = #{storagePositionCode}


    and base.storage_position_name = #{storagePositionName}


    and base.storage_position_type = #{storagePositionType}


    and base.responsible_person_id = #{responsiblePersonId}


    and base.responsible_person_name = #{responsiblePersonName}


    and base.file_id = #{fileId}



    and base.create_time >= #{searchStartDate}


    and base.create_time <= #{searchEndDate}


order by directory.type, directory.waste_code
